INSERT INTO feature VALUES('nominal-data','types','Data types',NULL,'implemented','ordinary',NULL,'Nominal data declarations with constructors and case analysis over them; a constructor field may state its grade, `1` or `ω`, which the family''s description code keeps. Two families of one shape stay distinct: a constructor keeps its own family wherever a type of another is written for it, through an ascription, an alias, a signature or a field, and is carried to the other only along the path an equivalence makes. A constructor or a case at a type a definition computes reads it at its weak head, the family the definition returns; the printer spells such a constructor without its name (#3669).','core-checker kernel-core surface-lowering','corpus/model/data/data-enum.gandr corpus/model/data/data-maybe.gandr corpus/model/data/data-matched-arms.gandr corpus/surface/data-field-decorations.gandr corpus/ledger/syntax/data-declaration.gandr corpus/pathological/data/field-grade.gandr corpus/model/data/one-shape-families.gandr corpus/pathological/data/nominal-distinctness.gandr corpus/pathological/data/nested-nominal-mismatch.gandr crates/core-checker-base/tests/native_formers.rs','corpus/model/data/data-enum.gandr',NULL);
